{
  "name": "envelope-os",
  "version": "0.1.0",
  "description": "Penny — zero-based envelope budgeting over PocketSmith. Local-first, cloud-ready.",
  "type": "module",
  "private": true,
  "scripts": {
    "dev": "bun run src/server/index.ts",
    "backfill": "bun run scripts/backfill.ts",
    "sync": "bun run scripts/sync.ts",
    "migrate": "bun run scripts/migrate.ts",
    "codegen:pocketsmith": "bun run scripts/codegen-pocketsmith.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "serve:tailscale": "tailscale serve --bg https / http://127.0.0.1:8787"
  },
  "engines": {
    "bun": ">=1.1.0"
  }
}

/**
 * Deployment configuration. The ONLY module permitted to read DEPLOY_MODE
 * is the composition root (src/composition.ts). Business modules depend on
 * resolved interfaces, never on this value. Enforces ISC-50, ISC-51.
 */

export type DeployMode = "local" | "cloud";

export interface AppConfig {
  readonly deployMode: DeployMode;
  /** SQLite file path (local) — ignored by the Postgres adapter. */
  readonly sqlitePath: string;
  /** Postgres connection string (cloud) — undefined in local mode. */
  readonly postgresUrl?: string;
  /** Port the Hono server binds. Bound to 127.0.0.1 in local mode; fronted by tailscale serve. */
  readonly port: number;
  /** Public base path the SPA is mounted at. "/" local, "/budget" cloud. */
  readonly basePath: string;
}

/**
 * Resolve config from the environment. Called once, at the composition root.
 * Throws loudly on an unknown DEPLOY_MODE rather than defaulting silently.
 */
export function loadConfig(env: Record<string, string | undefined> = process.env): AppConfig {
  const raw = (env.DEPLOY_MODE ?? "local").trim().toLowerCase();
  if (raw !== "local" && raw !== "cloud") {
    throw new Error(`DEPLOY_MODE must be "local" or "cloud", got "${raw}"`);
  }
  const deployMode: DeployMode = raw;
  return {
    deployMode,
    sqlitePath: env.PENNY_SQLITE_PATH ?? `${env.HOME ?? "."}/.penny/penny.db`,
    postgresUrl: env.PENNY_POSTGRES_URL,
    port: Number(env.PENNY_PORT ?? "8787"),
    basePath: deployMode === "cloud" ? "/budget" : "/",
  };
}

/**
 * Authentication seam. Route handlers and business modules depend ONLY on the
 * resolved authenticated `userId` returned here — never on which implementation
 * is active. Enforces ISC-52 (local), ISC-53 (cloud magic-link).
 *
 *   Local  : Tailscale device trust + a PIN held in the SecretStore. 30-min idle session.
 *   Cloud  : passwordless email magic-link. Request link -> verify token -> mint session.
 *
 * The two implementations live in src/platform/auth/local.ts and auth/cloud.ts.
 */

export type UserId = string;

export interface Session {
  readonly userId: UserId;
  readonly issuedAt: number;
  readonly idleExpiresAt: number;
}

export interface AuthProvider {
  /**
   * Begin sign-in. Local: validate the PIN. Cloud: email a magic link.
   * Returns a session on immediate success (local PIN) or null when a
   * second step is required (cloud, link sent).
   */
  beginSignIn(input: BeginSignInInput): Promise<Session | null>;

  /**
   * Complete sign-in from a magic-link token (cloud) or refresh a PIN session.
   * Returns the session or throws on an invalid/expired token.
   */
  completeSignIn(token: string): Promise<Session>;

  /** Resolve and validate the session on an incoming request; null if unauthenticated or expired. */
  resolveSession(request: Request): Promise<Session | null>;

  /** Invalidate the active session. */
  signOut(session: Session): Promise<void>;
}

export type BeginSignInInput =
  | { readonly kind: "pin"; readonly pin: string }
  | { readonly kind: "email"; readonly email: string };

/** Thrown when a magic-link or PIN attempt fails. Never leaks which user exists. */
export class AuthError extends Error {}

/**
 * Per-user secret material seam. Keyed by userId so each tenant owns their own
 * PocketSmith developer key. This is what makes "give someone access with just
 * their email and their dev key" true. Enforces ISC-54 (local), ISC-55 (cloud KMS),
 * ISC-56 (never plaintext at rest / in logs).
 *
 *   Local : PAI secrets store / OS keychain / an encrypted local file.
 *   Cloud : envelope encryption via GCP KMS; ciphertext stored in the DB.
 *
 * Implementations live in src/platform/secrets/local.ts and secrets/cloud.ts.
 * A SecretStore implementation MUST NOT log secret values and MUST NOT return
 * them in error messages.
 */

import type { UserId } from "./auth.ts";

/** Named secrets a tenant can hold. Extend as needed; PocketSmith dev key is the first. */
export type SecretName = "pocketsmith_developer_key" | "auth_pin";

export interface SecretStore {
  /** Fetch a secret for a tenant. Returns null if unset. Never logs the value. */
  get(userId: UserId, name: SecretName): Promise<string | null>;

  /** Store/replace a secret for a tenant. Local: keychain/encrypted file. Cloud: KMS-encrypt then persist ciphertext. */
  set(userId: UserId, name: SecretName, value: string): Promise<void>;

  /** Remove a secret for a tenant (offboarding). */
  delete(userId: UserId, name: SecretName): Promise<void>;
}

/** Convenience: resolve the PocketSmith X-Developer-Key for a tenant, or throw if missing. */
export async function requirePocketSmithKey(store: SecretStore, userId: UserId): Promise<string> {
  const key = await store.get(userId, "pocketsmith_developer_key");
  if (!key) throw new Error(`No PocketSmith developer key configured for user ${userId}`);
  return key;
}

/**
 * Persistence seam. NO business module imports bun:sqlite directly — they depend
 * on this interface. Enforces ISC-49 (every tenant query scoped by userId),
 * ISC-57 (no direct bun:sqlite import outside the adapter), ISC-58 (Postgres
 * adapter passes the same suite), ISC-59 (no SQLite-only SQL in business code).
 *
 *   Local : SqliteStore over bun:sqlite (src/store/sqlite.ts)
 *   Cloud : PostgresStore (src/store/postgres.ts)
 *
 * Both adapters MUST pass test/store.suite.ts identically. Every method takes
 * the authenticated userId as its first argument; there is no unscoped tenant read.
 */

import type { UserId } from "./auth.ts";

export interface Tx {
  readonly id: string;
  readonly date: string; // ISO date
  readonly amountCents: number; // signed; negative = outflow
  readonly accountId: string;
  readonly categoryId: string | null;
  readonly envelopeId: string | null;
  readonly payee: string;
  readonly isTransfer: boolean;
  readonly isPending: boolean;
  readonly rawJson: string;
}

export interface Envelope {
  readonly id: string;
  readonly name: string;
  readonly group: string;
  readonly rolloverRule: "roll_positive_zero_negative" | "roll_all" | "drain_to_zero" | "annual_reset_jan";
  readonly targetType: "monthly" | "annual" | "sinking" | "no_target";
  readonly targetAmountCents: number;
}

export interface LedgerEvent {
  readonly id: string;
  readonly ts: number;
  readonly actor: "sync" | "ui" | "agent";
  readonly correlationId: string;
  readonly kind: string;
  readonly payloadJson: string;
}

/**
 * The store contract. Tenant scoping is mandatory: every method that touches
 * tenant data takes userId first. Cross-tenant isolation is asserted in tests.
 */
export interface Store {
  migrate(): Promise<void>;

  upsertTransactions(userId: UserId, txs: readonly Tx[]): Promise<void>;
  listTransactions(userId: UserId, opts?: { envelopeId?: string; since?: string }): Promise<Tx[]>;

  upsertEnvelope(userId: UserId, e: Envelope): Promise<void>;
  listEnvelopes(userId: UserId): Promise<Envelope[]>;

  appendEvent(userId: UserId, e: LedgerEvent): Promise<void>;
  writeDailySnapshot(userId: UserId, date: string): Promise<void>;

  /** Last successful sync timestamp for incremental updated_since. */
  getLastSyncAt(userId: UserId): Promise<string | null>;
  setLastSyncAt(userId: UserId, iso: string): Promise<void>;

  close(): Promise<void>;
}

/**
 * Composition root. THE ONLY module that reads DEPLOY_MODE and decides which
 * concrete adapters back the AuthProvider, SecretStore, and Store interfaces.
 * Everything downstream receives resolved interfaces and is blind to the mode.
 * This is the single seam that turns "local-first" into "cloud" — by config,
 * not by code. Proves ISC-50, ISC-51.
 *
 * NOTE: concrete adapters (local/* and cloud/*) are built by the ingest-spine
 * and platform-seams work. Imports are wired here so the contract is visible;
 * the build fills in the implementations behind these interfaces.
 */

import { loadConfig, type AppConfig } from "./platform/config.ts";
import type { AuthProvider } from "./platform/auth.ts";
import type { SecretStore } from "./platform/secrets.ts";
import type { Store } from "./platform/store.ts";

export interface Container {
  readonly config: AppConfig;
  readonly store: Store;
  readonly secrets: SecretStore;
  readonly auth: AuthProvider;
}

export async function buildContainer(): Promise<Container> {
  const config = loadConfig();

  // --- Store adapter ---
  const store: Store =
    config.deployMode === "cloud"
      ? new (await import("./store/postgres.ts")).PostgresStore(config.postgresUrl!)
      : new (await import("./store/sqlite.ts")).SqliteStore(config.sqlitePath);
  await store.migrate();

  // --- SecretStore adapter ---
  const secrets: SecretStore =
    config.deployMode === "cloud"
      ? new (await import("./platform/secrets/cloud.ts")).KmsSecretStore(store)
      : new (await import("./platform/secrets/local.ts")).LocalSecretStore();

  // --- AuthProvider adapter ---
  const auth: AuthProvider =
    config.deployMode === "cloud"
      ? new (await import("./platform/auth/cloud.ts")).MagicLinkAuth(store, secrets)
      : new (await import("./platform/auth/local.ts")).TailscalePinAuth(secrets);

  return { config, store, secrets, auth };
}

